import { createChart, CrosshairMode, CandlestickSeries, AreaSeries, LineSeries, HistogramSeries } from '../../dist/lightweight-charts.standalone.development.mjs';

export class Chart {
    constructor(container) {
        this.container = container;
        this.seriesMap = new Map();
        this.overlays = new Map();

        // Overlay Layer
        this.overlayLayer = document.createElement('div');
        this.overlayLayer.style.position = 'absolute';
        this.overlayLayer.style.top = '0';
        this.overlayLayer.style.left = '0';
        this.overlayLayer.style.width = '100%';
        this.overlayLayer.style.height = '100%';
        this.overlayLayer.style.pointerEvents = 'none'; // Passthrough clicks
        this.overlayLayer.style.overflow = 'hidden';
        this.overlayLayer.style.zIndex = '10'; // Above chart canvas
        container.style.position = 'relative'; // Ensure absolute positioning works relative to this
        container.appendChild(this.overlayLayer);

        this.chart = createChart(container, {
            width: container.clientWidth,
            height: container.clientHeight,
            layout: {
                background: { color: '#0C0C0C' },
                textColor: '#F9F9F9',
            },
            grid: {
                vertLines: { color: '#404040' },
                horzLines: { color: '#404040' },
            },
            crosshair: {
                mode: CrosshairMode.Normal,
            },
            rightPriceScale: {
                borderColor: 'rgba(197, 203, 206, 0.8)',
            },
            timeScale: {
                borderColor: 'rgba(197, 203, 206, 0.8)',
                timeVisible: true,
                secondsVisible: false,
            },
            kineticScroll: {
                touch: true,
                mouse: true,
            },
        });

        // Handle Resize
        window.addEventListener('resize', () => {
            this.chart.applyOptions({
                width: container.clientWidth,
                height: container.clientHeight
            });
            this.updateOverlays();
        });

        this.chart.timeScale().subscribeVisibleTimeRangeChange(() => {
            this.updateOverlays();
        });
    }

    subscribeCrosshairMove(callback) {
        this.chart.subscribeCrosshairMove(callback);
    }

    addOverlay(id, content, positionCallback) {
        const div = document.createElement('div');
        div.id = id;
        div.style.position = 'absolute';

        if (typeof content === 'string') {
            div.innerHTML = content;
        } else if (content instanceof HTMLElement) {
            div.appendChild(content);
        }

        this.overlayLayer.appendChild(div);
        this.overlays.set(id, { element: div, callback: positionCallback });

        // Initial positioning
        this.updateOverlays();
        return div;
    }

    removeOverlay(id) {
        const overlay = this.overlays.get(id);
        if (overlay) {
            this.overlayLayer.removeChild(overlay.element);
            this.overlays.delete(id);
        }
    }

    updateOverlays() {
        this.overlays.forEach((overlay) => {
            const pos = overlay.callback(this);
            if (pos && pos.visible !== false) {
                overlay.element.style.display = 'block';
                if (pos.x !== undefined) overlay.element.style.left = `${pos.x}px`;
                if (pos.y !== undefined) overlay.element.style.top = `${pos.y}px`;
                // Allow centering if requested
                if (pos.centerX) overlay.element.style.transform = 'translateX(-50%)';
            } else {
                overlay.element.style.display = 'none';
            }
        });
    }

    addSeries(type, name, options = {}) {
        let series;
        switch (type.toLowerCase()) {
            case 'candlestick':
                series = this.chart.addSeries(CandlestickSeries, options);
                break;
            case 'area':
                series = this.chart.addSeries(AreaSeries, options);
                break;
            case 'line':
                series = this.chart.addSeries(LineSeries, options);
                break;
            case 'histogram':
                series = this.chart.addSeries(HistogramSeries, options);
                break;
            default:
                throw new Error(`Unsupported series type: ${type}`);
        }

        this.seriesMap.set(name, series);
        return series;
    }

    addCustomSeries(customSeriesDefinition, name, options = {}) {
        const series = this.chart.addCustomSeries(customSeriesDefinition, options);
        this.seriesMap.set(name, series);
        return series;
    }

    getSeriesByName(name) {
        return this.seriesMap.get(name);
    }

    getSeries() {
        return Array.from(this.seriesMap.values());
    }

    removeSeries(name) {
        const series = this.seriesMap.get(name);
        if (series) {
            this.chart.removeSeries(series);
            this.seriesMap.delete(name);
        }
    }

    fitContent() {
        this.chart.timeScale().fitContent();
    }

    applyOptions(options) {
        this.chart.applyOptions(options);
    }
}
